use strict;
use warnings;
my $REPO = "/bench/repo";
my @DATA_PREFIXES = ("/bench/repo/store", "/bench/repo/proto/gen/store");
my @ENTITIES = qw(Attachment Memo MemoRelation InstanceSetting User UserSetting IdentityProvider Inbox Reaction MemoShare UserIdentity);

sub is_data_layer {
    my ($d) = @_;
    for my $p (@DATA_PREFIXES) {
        return 1 if $d eq $p || index($d, "$p/") == 0;
    }
    return 0;
}

# find all go files
my %pkg_files;
opendir(my $dh, $REPO) or die $!;
# use find via shell
my @files = `find $REPO -name "*.go" -not -path "*/.git/*"`;
chomp @files;

for my $f (@files) {
    my $d = $f;
    $d =~ s{/[^/]+$}{};
    push @{$pkg_files{$d}}, $f;
}

my %entity_pkgs;
for my $entity (@ENTITIES) {
    my $pat = qr/\bstore\.(?:$entity|Find$entity|Update$entity|Delete$entity)\b/;
    for my $pkg (sort keys %pkg_files) {
        next if is_data_layer($pkg);
        for my $f (@{$pkg_files{$pkg}}) {
            open my $fh, "<", $f or next;
            my $ln = 0;
            while (<$fh>) {
                $ln++;
                if (/$pat/) {
                    my $rel = $pkg; $rel =~ s{^$REPO/}{};
                    $entity_pkgs{$entity}{$rel} = 1;
                }
            }
            close $fh;
        }
    }
}

print "=== RANKING ===\n";
my @ranked = sort { scalar(keys %{$entity_pkgs{$b}}) <=> scalar(keys %{$entity_pkgs{$a}}) } @ENTITIES;
for my $e (@ranked) {
    my @pkgs = sort keys %{$entity_pkgs{$e}};
    print "$e: ", scalar(@pkgs), " packages\n";
    for my $p (@pkgs) { print "  $p\n"; }
}
'

