for my $e (@ranked) {
    my @pkgs = sort keys %{$entity_pkgs{$e}};
    my $total_refs = 0; $total_refs += $_ for values %{$entity_pkgs{$e}};
    print "\n$e: ", scalar(@pkgs), " packages, ~$total_refs ref lines\n";
    for my $p (@pkgs) {
        print "  $p ($entity_pkgs{$e}{$p} refs)\n";
        for my $ev (@{$entity_evidence{$e}{$p} // []}) { print "    e.g. $ev\n"; }
    }
}
