use strict;
use warnings;
my $REPO = "/bench/repo";
my @DATA_PREFIXES = ("/bench/repo/store", "/bench/repo/proto/gen/store", "/bench/repo/proto/gen/api");

sub is_excluded {
    my ($d) = @_;
    for my $p (@DATA_PREFIXES) {
        return 1 if $d eq $p || index($d, "$p/") == 0;
    }
    return 0;
}

my %entities = (
    Attachment => [qr/\bstore\.(?:Attachment|FindAttachment|UpdateAttachment|DeleteAttachment)\b/, qr/\bstorepb\.(?:AttachmentPayload|AttachmentStorageType)\b/],
    Memo => [qr/\bstore\.(?:Memo|FindMemo|UpdateMemo|DeleteMemo)\b/, qr/\bstorepb\.MemoPayload\b/],
    MemoRelation => [qr/\bstore\.(?:MemoRelation|FindMemoRelation|DeleteMemoRelation)\b/, undef],
    InstanceSetting => [qr/\bstore\.(?:InstanceSetting|FindInstanceSetting|DeleteInstanceSetting)\b/, qr/\bstorepb\.InstanceSetting\b|\bInstanceSettingKey\b/],
    User => [qr/\bstore\.(?:User|FindUser|UpdateUser|DeleteUser)\b/, undef],
    UserSetting => [qr/\bstore\.(?:UserSetting|FindUserSetting|DeleteUserSetting|PATQueryResult|RefreshTokenQueryResult)\b/, qr/\bstorepb\.UserSetting\b|\bUserSetting_Key\b/],
    IdentityProvider => [qr/\bstore\.(?:IdentityProvider|FindIdentityProvider|UpdateIdentityProvider|DeleteIdentityProvider)\b/, qr/\bstorepb\.IdentityProvider\b/],
    Inbox => [qr/\bstore\.(?:Inbox|FindInbox|UpdateInbox|DeleteInbox)\b/, qr/\bstorepb\.InboxMessage\b/],
    Reaction => [qr/\bstore\.(?:Reaction|FindReaction|DeleteReaction)\b/, undef],
    MemoShare => [qr/\bstore\.(?:MemoShare|FindMemoShare|DeleteMemoShare)\b/, undef],
    UserIdentity => [qr/\bstore\.(?:UserIdentity|FindUserIdentity|DeleteUserIdentity)\b/, undef],
);

my @files = `find $REPO -name "*.go" -not -path "*/.git/*"`;
chomp @files;
my %pkg_files;
for my $f (@files) {
    my $d = $f; $d =~ s{/[^/]+$}{};
    push @{$pkg_files{$d}}, $f;
}

my %entity_pkgs;
for my $entity (keys %entities) {
    my ($pat1, $pat2) = @{$entities{$entity}};
    for my $pkg (sort keys %pkg_files) {
        next if is_excluded($pkg);
        for my $f (@{$pkg_files{$pkg}}) {
            open my $fh, "<", $f or next;
            while (my $line = <$fh>) {
                my $match = ($pat1 && $line =~ /$pat1/) || ($pat2 && $line =~ /$pat2/);
                next unless $match;
                my $rel = $pkg; $rel =~ s{^$REPO/}{};
                $entity_pkgs{$entity}{$rel}++;
            }
            close $fh;
        }
    }
}

# Also count non-test packages only
sub is_test_pkg { $_[0] =~ m{/test$} || $_[0] =~ /_test\.go$/ }

print "=== ALL EXTERNAL PACKAGES (excl data layer + proto/gen/api) ===\n";
my @ranked = sort { scalar(keys %{$entity_pkgs{$b}}) <=> scalar(keys %{$entity_pkgs{$a}}) } keys %entities;
for my $e (@ranked) {
    my @pkgs = sort keys %{$entity_pkgs{$e}};
    print "$e: ", scalar(@pkgs), " -> ", join(", ", @pkgs), "\n";
}

print "\n=== NON-TEST PACKAGES ONLY ===\n";
for my $e (@ranked) {
    my @pkgs = grep { !/\\/test$/ && $_ !~ /\/test$/ } sort keys %{$entity_pkgs{$e}};
    @pkgs = grep { $_ !~ /\/test$/ } sort keys %{$entity_pkgs{$e}};
    print "$e: ", scalar(@pkgs), " -> ", join(", ", @pkgs), "\n";
}
'

