my @EXCL=("/bench/repo/store","/bench/repo/proto/gen/store","/bench/repo/proto/gen/api");
sub excl { my $d=shift; for(@EXCL){return 1 if $d eq $_ || index($d,"$_/")==0} 0 }
my %ent=(
 User=>[qr/\bstore\.(?:User|FindUser|UpdateUser|DeleteUser)\b/],
 Memo=>[qr/\bstore\.(?:Memo|FindMemo|UpdateMemo|DeleteMemo)\b/, qr/\bstorepb\.MemoPayload\b/],
);
