    open F,"<",$f; my $c=do{local $/;<F>}; close F;
    my $m=0; $m=1 if $ent{$e}[0] && $c=~/$ent{$e}[0]/; $m=1 if $ent{$e}[1] && $c=~/$ent{$e}[1]/;
    next unless $m;
    my $rel=$d; $rel=~s{^$REPO/}{}; $pkgs{$rel}=1; $files{$f}=1;
  }
  print "$e: ",scalar(keys %pkgs)," pkgs, ",scalar(keys %files)," files\n";
}
'

